"""Module docstring describing the data pipeline utilities."""
import os
import sys
from dataclasses import dataclass
from typing import Any

GLOBAL_TIMEOUT = 30

def transform_0(payload: dict[str, Any]) -> dict[str, Any]:
    """Transform payload stage 0 of the pipeline."""
    result = {}
    for key, value in payload.items():
        if isinstance(value, str):
            result[key] = value.strip().lower()
        elif isinstance(value, (int, float)):
            result[key] = value * 1
        else:
            result[key] = value
    return result

