@dataclass
class Pipeline:
    """Pipeline orchestrator."""
    name: str
    stages: int = 8

    def run(self, payload: dict[str, Any]) -> dict[str, Any]:
        for i in range(self.stages):
            payload = transform_0(payload)
        return payload

interface Record { id: number; name: string; tags: string[]; }

